<?php $shop=$sale['shop'];$customer=$sale['customer'];$states=App\Services\SalesSettingsService::states(); ?>
<article class="invoice-document <?= e($format??'a4') ?>"><header class="invoice-heading"><div><h2><?= e($shop['legal_name']) ?></h2><p><?= nl2br(e($shop['address'])) ?></p><p><?= e($states[$shop['state_code']]??$shop['state_code']) ?> · <?= e($shop['state_code']) ?></p><?php if($shop['gstin']): ?><p>GSTIN: <?= e($shop['gstin']) ?></p><?php endif; ?></div><div><h2><?= e($sale['document_type']) ?></h2><strong><?= e($sale['invoice_number']) ?></strong><p><?= e(local_datetime($sale['created_at'])) ?></p><?php if($sale['cancellation_id']): ?><strong class="invoice-cancelled">CANCELLED · #<?= (int)$sale['cancellation_id'] ?></strong><?php endif; ?></div></header>
<div class="invoice-customer"><p><strong>Bill to: <?= e($customer['name']) ?></strong><?php if(!empty($customer['phone'])): ?><br><?= e($customer['phone']) ?><?php endif; ?><?php if(!empty($customer['address'])): ?><br><?= nl2br(e($customer['address'])) ?><?php endif; ?><?php if(!empty($customer['state_code'])): ?><br><?= e($states[$customer['state_code']]??$customer['state_code']) ?> (<?= e($customer['state_code']) ?>)<?php endif; ?><?php if(!empty($customer['gstin'])): ?><br>GSTIN: <?= e($customer['gstin']) ?><?php endif; ?></p><p>Place of supply: <?= e($states[$sale['place_of_supply']]??$sale['place_of_supply']) ?> (<?= e($sale['place_of_supply']) ?>)<br>Prices <?= e($shop['price_mode']) ?><?= $shop['registration_type']==='regular'?' of GST':'' ?></p></div>
<div class="invoice-lines"><table><thead><tr><th>Item / SKU / HSN or SAC</th><th>Qty</th><th>Rate</th><th>Discount</th><th><?= $shop['registration_type']==='regular'?'Taxable':'Net' ?></th><?php if($shop['registration_type']==='regular'): ?><th>GST</th><?php endif; ?><th>Total</th></tr></thead><tbody><?php $serviceHeading=false;foreach(array_merge($sale['items'],$sale['services']) as $item): $l=$item['line'];$service=($l['line_type']??'product')==='service'; ?><?php if($service && !$serviceHeading): $serviceHeading=true; ?><tr class="invoice-service-heading"><th colspan="<?= $shop['registration_type']==='regular'?7:6 ?>">Labour charges</th></tr><?php endif; ?><tr><td><strong><?= e($l['name']) ?></strong><small><?= $service?'Labour / Service':e($l['sku']) ?><?= $l['hsn_code']?e(($service?' · SAC ':' · HSN ').$l['hsn_code']):'' ?><?php if(($l['place_of_supply']??$sale['place_of_supply'])!==$sale['place_of_supply']): ?><br>Supply: <?= e($states[$l['place_of_supply']]) ?> (<?= e($l['place_of_supply']) ?>)<?php endif; ?></small></td><td data-label="Qty"><?= quantity($l['quantity']) ?></td><td data-label="Rate"><?= money($l['price']) ?></td><td data-label="Discount"><?= money(bcadd($l['discount'],$l['bill_discount'],2)) ?></td><td data-label="Net"><?= money($l['taxable']) ?></td><?php if($shop['registration_type']==='regular'): ?><td data-label="GST"><?= e($l['tax_rate']) ?>%<small><?php if(bccomp($l['igst'],'0',2)>0): ?>IGST <?= money($l['igst']) ?><?php else: ?>CGST <?= money($l['cgst']) ?><br>SGST <?= money($l['sgst']) ?><?php endif; ?></small></td><?php endif; ?><td data-label="Total"><?= money($l['total']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<dl class="pos-totals invoice-totals"><dt>Subtotal (price basis)</dt><dd><?= money($sale['subtotal']) ?></dd><dt>Discount</dt><dd><?= money($sale['discount']) ?></dd><dt><?= $shop['registration_type']==='regular'?'Taxable amount':'Net amount' ?></dt><dd><?= money($sale['taxable']) ?></dd><?php if($shop['registration_type']==='regular'): ?><dt>CGST</dt><dd><?= money($sale['cgst']) ?></dd><dt>SGST</dt><dd><?= money($sale['sgst']) ?></dd><dt>IGST</dt><dd><?= money($sale['igst']) ?></dd><?php endif; ?><dt><strong>Grand total</strong></dt><dd><strong><?= money($sale['total']) ?></strong></dd><dt>Amount received</dt><dd><?= money($sale['amount_received']) ?></dd><dt>Change returned</dt><dd><?= money($sale['change_due']) ?></dd><dt>Amount applied</dt><dd><?= money($sale['amount_paid']) ?></dd><dt>Balance at posting</dt><dd><?= money($sale['balance_due']) ?></dd></dl>
<?php $methods=[];foreach($sale['payments'] as $payment)if(!$payment['reverses_payment_id'])$methods[]=strtoupper($payment['method']); ?><p>Payment: <?= e(implode(', ',array_unique($methods))?:'Credit') ?> · <?= $sale['cancellation_id']?'Cancelled / payments reversed':(bccomp($sale['balance_due'],'0',2)===0?'Paid':(bccomp($sale['amount_paid'],'0',2)>0?'Partially paid':'Unpaid')) ?></p>
<?php if($sale['cancellation_id']): ?><p>Cancelled <?= e(local_datetime($sale['cancelled_at'])) ?>: <?= e($sale['cancellation_reason']) ?>. Original amounts retained above; current outstanding ₹0.00.</p><?php endif; ?>
<?php if($shop['registration_type']==='composition'): ?><p>Composition taxable person, not eligible to collect tax on supplies.</p><?php elseif($shop['registration_type']==='unregistered'): ?><p>No GST collected.</p><?php else: ?><p>Tax payable on reverse charge: No.</p><?php endif; ?><p><?= nl2br(e($shop['footer'])) ?></p><footer class="invoice-footer"><span>Prepared by <?= e($sale['cashier']) ?></span><span>Authorised signatory: __________________</span></footer></article>
